// WsPipelineProgress GET /ws/pipeline/progress
func (s *OperationsService) WsPipelineProgress() string {
	path := "/ws/pipeline/progress"
	return socketURL(s.c.BaseURL(), path)
}

// WsProgressByTrackId GET /ws/progress/{track_id}
func (s *OperationsService) WsProgressByTrackId(trackId string) string {
	path := fmt.Sprintf("/ws/progress/%s", encodePathParam(trackId))
	return socketURL(s.c.BaseURL(), path)
}

func parseEvents(text string) string {
	var events []string
	for _, block := range strings.Split(text, "\n\n") {
		for _, line := range strings.Split(block, "\n") {
			if !strings.HasPrefix(line, "data:") {
				continue
			}
			data := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
			if data != "" && data != "[DONE]" {
				events = append(events, data)
			}
		}
	}
	return strings.Join(events, "\n")
}

func socketURL(base, path string) string {
	root := strings.TrimRight(base, "/")
	switch {
	case strings.HasPrefix(root, "https://"):
		root = "wss://" + strings.TrimPrefix(root, "https://")
	case strings.HasPrefix(root, "http://"):
		root = "ws://" + strings.TrimPrefix(root, "http://")
	}
	return root + path
}

func encodePathParam(value string) string {
	parts := strings.Split(value, "/")
	for i, part := range parts {
		parts[i] = url.PathEscape(part)
	}
	return strings.Join(parts, "/")
}
